WITH ft AS (SELECT DISTINCT "track_id" FROM sqlite_scan('C:/Users/VikasVijigiri/Documents/DataAgentBench/query_music_brainz_20k/query_dataset/tracks.db', 'tracks') WHERE lower("artist") = lower('Beyoncé') AND (lower("title") LIKE '%get%bodied%' OR lower(REPLACE("title", ' ', '')) LIKE '%getmebodied%')), fs AS (SELECT "track_id", "revenue_usd" FROM "sales" WHERE "store" = 'Apple Music' AND "country" = 'Canada') SELECT COALESCE(SUM(fs."revenue_usd"), 0.0) AS "total_revenue_usd" FROM fs JOIN ft ON fs."track_id" = ft."track_id";